import pygame

def bounce_y(y, vy, radius, height):
    if y <= radius and vy < 0:
        return radius, -vy
    if y >= height - radius and vy > 0:
        return height - radius, -vy
    return y, vy

def left_contact(ball, paddle, vx):
    if pygame.Rect(ball).colliderect(pygame.Rect(paddle)) and vx < 0:
        return -vx
    return vx
